#include <string>
#include <vector>

namespace
{
    std::string convert(const std::string& text, const char* ending)
    {
        std::string out;
        for (std::size_t i{ 0 }; i < text.size(); ++i)
        {
            const char c{ text[i] };
            if (c == '\r') { out += ending; if (i + 1 < text.size() && text[i + 1] == '\n') ++i; }
            else if (c == '\n') out += ending;
            else out += c;
        }
        return out;
    }
}

std::string toClipboard(const std::string& text) { return convert(text, "\r\n"); }
std::string fromClipboard(const std::string& text) { return convert(text, "\n"); }

std::string buildFileList(const std::vector<std::string>& paths)
{
    std::string out;
    for (const std::string& p : paths) { out += p; out += '\0'; }
    if (out.empty()) out += '\0';
    out += '\0';
    return out;
}

std::vector<std::string> parseFileList(const std::string& data)
{
    std::vector<std::string> paths;
    std::size_t pos{ 0 };
    while (pos < data.size())
    {
        const std::size_t end{ data.find('\0', pos) };
        const std::string p{ data.substr(pos, end == std::string::npos ? std::string::npos : end - pos) };
        if (p.empty()) break;
        paths.push_back(p);
        if (end == std::string::npos) break;
        pos = end + 1;
    }
    return paths;
}

